cat > color.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
	"syscall"
	"unsafe"
)

type Attribute int

const (
	Reset Attribute = 0
	Bold  Attribute = 1
)

const (
	FgRed     Attribute = 31
	FgMagenta Attribute = 35
	FgWhite   Attribute = 37
)

const (
	FgHiBlack   Attribute = 90
	FgHiRed     Attribute = 91
	FgHiGreen   Attribute = 92
	FgHiYellow  Attribute = 93
	FgHiBlue    Attribute = 94
	FgHiMagenta Attribute = 95
	FgHiCyan    Attribute = 96
	FgHiWhite   Attribute = 97
)

// resetFor maps attributes to their dedicated reset code.
var resetFor = map[Attribute]int{
	Bold: 22,
}

func isTerminal(fd int) bool {
	var t syscall.Termios
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	return e == 0
}

// NoColor disables all color output when true.
var NoColor = os.Getenv("NO_COLOR") != "" || os.Getenv("TERM") == "dumb" || !isTerminal(int(os.Stdout.Fd()))

type Color struct {
	params []Attribute
}

func NewColor(attrs ...Attribute) *Color {
	return &Color{params: attrs}
}

func (c *Color) sequence() string {
	parts := make([]string, len(c.params))
	for i, a := range c.params {
		parts[i] = strconv.Itoa(int(a))
	}
	return strings.Join(parts, ";")
}

func (c *Color) format() string {
	return "\x1b[" + c.sequence() + "m"
}

func (c *Color) unformat() string {
	parts := make([]string, len(c.params))
	for i, a := range c.params {
		r := int(Reset)
		if v, ok := resetFor[a]; ok {
			r = v
		}
		parts[i] = strconv.Itoa(r)
	}
	return "\x1b[" + strings.Join(parts, ";") + "m"
}

func (c *Color) wrap(s string) string {
	if NoColor {
		return s
	}
	return c.format() + s + c.unformat()
}

func (c *Color) Sprint(a ...interface{}) string {
	return c.wrap(fmt.Sprint(a...))
}

// Fprintf writes the colored formatted text, resetting all attributes afterwards.
func (c *Color) Fprintf(w io.Writer, format string, a ...interface{}) {
	if !NoColor {
		fmt.Fprint(w, c.format())
	}
	fmt.Fprintf(w, format, a...)
	if !NoColor {
		fmt.Fprint(w, "\x1b[0m")
	}
}

func (c *Color) Printf(format string, a ...interface{}) {
	c.Fprintf(os.Stdout, format, a...)
}
EOF"}

