{"command":"cd /workspace; cat > flags.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

type flagErrorType int

const (
	errUnknown flagErrorType = iota
	errExpectedArgument
	errUnknownFlag
	errMarshal
	errHelp
	errNoArgumentForBool
)

type flagError struct {
	Type    flagErrorType
	Message string
}

func (e *flagError) Error() string { return e.Message }

func newFlagError(t flagErrorType, msg string) *flagError {
	return &flagError{Type: t, Message: msg}
}

type optKind int

const (
	kindInt optKind = iota
	kindBool
	kindHelp
)

type optionDef struct {
	short       rune
	long        string
	description string
	defValue    string
	kind        optKind
	group       int
	set         func(arg *string) error
}

func (o *optionDef) canArgument() bool { return o.kind == kindInt }

func (o *optionDef) String() string {
	if o.short != 0 {
		if o.long != "" {
			return fmt.Sprintf("-%c, --%s", o.short, o.long)
		}
		return fmt.Sprintf("-%c", o.short)
	}
	return "--" + o.long
}

type Options struct {
	Count     int
	Privilege bool
	Version   bool
}

type cliParser struct {
	name            string
	usage           string
	longDescription string
	groups          []string
	options         []*optionDef
	shortNames      map[string]*optionDef
	longNames       map[string]*optionDef
}

func newCLIParser(opts *Options) *cliParser {
	p := &cliParser{
		name:            "pingu",
		usage:           "[OPTIONS] HOST",
		longDescription: "`ping` command but with pingu",
		groups:          []string{"Application Options", "Help Options"},
		shortNames:      map[string]*optionDef{},
		longNames:       map[string]*optionDef{},
	}
	opts.Count = 20
	p.options = []*optionDef{
		{
			short: 'c', long: "count", description: "Stop after <count> replies",
			defValue: "20", kind: kindInt, group: 0,
			set: func(arg *string) error {
				v, err := strconv.ParseInt(*arg, 10, 64)
				if err != nil {
					return err
				}
				opts.Count = int(v)
				return nil
			},
		},
		{
			short: 'P', long: "privilege", description: "Enable privileged mode",
			kind: kindBool, group: 0,
			set: func(arg *string) error { opts.Privilege = true; return nil },
		},
		{
			short: 'V', long: "version", description: "Show version",
			kind: kindBool, group: 0,
			set: func(arg *string) error { opts.Version = true; return nil },
		},
		{
			short: 'h', long: "help", description: "Show this help message",
			kind: kindHelp, group: 1,
			set: func(arg *string) error {
				return newFlagError(errHelp, p.helpText())
			},
		},
	}
	for _, o := range p.options {
		p.shortNames[string(o.short)] = o
		p.longNames[o.long] = o
	}
	return p
}

type parseState struct {
	args    []string
	retargs []string
}

func (s *parseState) eof() bool { return len(s.args) == 0 }

func (s *parseState) pop() string {
	if len(s.args) == 0 {
		return ""
	}
	a := s.args[0]
	s.args = s.args[1:]
	return a
}

func argumentIsOption(arg string) bool {
	if len(arg) > 1 && arg[0] == '-' && arg[1] != '-' {
		return true
	}
	if len(arg) > 2 && arg[0] == '-' && arg[1] == '-' && arg[2] != '-' {
		return true
	}
	return false
}

func stripOptionPrefix(optname string) (string, string, bool) {
	if strings.HasPrefix(optname, "--") {
		return "--", optname[2:], true
	} else if strings.HasPrefix(optname, "-") {
		return "-", optname[1:], false
	}
	return "", optname, false
}

func splitOption(option string, islong bool) (string, *string) {
	if len(option) == 0 {
		return option, nil
	}
	pos := strings.Index(option, "=")
	if (islong && pos >= 0) || (!islong && pos == 1) {
		rest := option[pos+1:]
		return option[:pos], &rest
	}
	return option, nil
}

func unquoteIfPossible(s string) (string, error) {
	if len(s) == 0 || s[0] != '"' {
		return s, nil
	}
	return strconv.Unquote(s)
}

func (p *cliParser) isValidValue(o *optionDef, arg string) error {
	if argumentIsOption(arg) && !(o.kind == kindInt && len(arg) > 1 && arg[0] == '-' && arg[1] >= '0' && arg[1] <= '9') {
		return fmt.Errorf("expected argument for flag `%s', but got option `%s'", o, arg)
	}
	return nil
}

func (p *cliParser) marshalError(o *optionDef, err error) *flagError {
	return newFlagError(errMarshal, fmt.Sprintf("invalid argument for flag `%s' (expected int): %s", o, err.Error()))
}

func (p *cliParser) parseOption(s *parseState, o *optionDef, canarg bool, argument *string) error {
	var err error
	if !o.canArgument() {
		if argument != nil {
			return newFlagError(errNoArgumentForBool, fmt.Sprintf("bool flag `%s' cannot have an argument", o))
		}
		err = o.set(nil)
	} else if argument != nil || (canarg && !s.eof()) {
		var arg string
		if argument != nil {
			arg = *argument
		} else {
			arg = s.pop()
			if verr := p.isValidValue(o, arg); verr != nil {
				// The message is used as a format string, mirroring the
				// behaviour of the reference implementation.
				return newFlagError(errExpectedArgument, fmt.Sprintf(verr.Error()))
			} else if arg == "--" {
				return newFlagError(errExpectedArgument, fmt.Sprintf("expected argument for flag `%s', but got double dash `--'", o))
			}
		}
		arg, err = unquoteIfPossible(arg)
		if err == nil {
			err = o.set(&arg)
		}
	} else {
		err = newFlagError(errExpectedArgument, fmt.Sprintf("expected argument for flag `%s'", o))
	}
	if err != nil {
		if _, ok := err.(*flagError); !ok {
			err = p.marshalError(o, err)
		}
	}
	return err
}

func (p *cliParser) splitShortConcatArg(optname string) (string, *string) {
	c, n := utf8.DecodeRuneInString(optname)
	if n == len(optname) {
		return optname, nil
	}
	first := string(c)
	if o := p.shortNames[first]; o != nil && o.canArgument() {
		arg := optname[n:]
		return first, &arg
	}
	return optname, nil
}

func (p *cliParser) parseShort(s *parseState, optname string, argument *string) error {
	if argument == nil {
		optname, argument = p.splitShortConcatArg(optname)
	}
	for i, c := range optname {
		shortname := string(c)
		if o := p.shortNames[shortname]; o != nil {
			canarg := i+utf8.RuneLen(c) == len(optname)
			if err := p.parseOption(s, o, canarg, argument); err != nil {
				return err
			}
		} else {
			return newFlagError(errUnknownFlag, fmt.Sprintf("unknown flag `%s'", shortname))
		}
		argument = nil
	}
	return nil
}

func (p *cliParser) parseLong(s *parseState, name string, argument *string) error {
	if o := p.longNames[name]; o != nil {
		return p.parseOption(s, o, true, argument)
	}
	return newFlagError(errUnknownFlag, fmt.Sprintf("unknown flag `%s'", name))
}

// Parse processes the command line arguments, returning the remaining
// positional arguments.
func (p *cliParser) Parse(args []string) ([]string, error) {
	s := &parseState{args: append([]string(nil), args...)}
	for !s.eof() {
		arg := s.pop()
		if arg == "--" {
			s.retargs = append(s.retargs, s.args...)
			break
		}
		if !argumentIsOption(arg) {
			s.retargs = append(s.retargs, arg)
			continue
		}
		_, optname, islong := stripOptionPrefix(arg)
		optname, argument := splitOption(optname, islong)
		var err error
		if islong {
			err = p.parseLong(s, optname, argument)
		} else {
			err = p.parseShort(s, optname, argument)
		}
		if err != nil {
			return nil, err
		}
	}
	return s.retargs, nil
}

type winsize struct {
	row, col       uint16
	xpixel, ypixel uint16
}

func terminalColumns() int {
	ws := winsize{}
	syscall.Syscall(syscall.SYS_IOCTL, uintptr(0), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	return int(ws.col)
}

func wrapText(s string, l int, prefix string) string {
	var ret string
	if l < 10 {
		l = 10
	}
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		var retline string
		line = strings.TrimSpace(line)
		for len(line) > l {
			suffix := ""
			pos := strings.LastIndex(line[:l], " ")
			if pos < 0 {
				pos = l - 1
				suffix = "-\n"
			}
			if len(retline) != 0 {
				retline += "\n" + prefix
			}
			retline += strings.TrimSpace(line[:pos]) + suffix
			line = strings.TrimSpace(line[pos:])
		}
		if len(line) > 0 {
			if len(retline) != 0 {
				retline += "\n" + prefix
			}
			retline += line
		}
		if len(ret) > 0 {
			ret += "\n"
			if len(retline) > 0 {
				ret += prefix
			}
		}
		ret += retline
	}
	return ret
}

func (p *cliParser) helpText() string {
	cols := terminalColumns()
	if cols <= 0 {
		cols = 80
	}

	maxLongLen := 0
	hasShort := false
	for _, o := range p.options {
		if o.short != 0 {
			hasShort = true
		}
		if l := utf8.RuneCountInString(o.long); l > maxLongLen {
			maxLongLen = l
		}
	}
	descStart := maxLongLen + 2
	if hasShort {
		descStart += 2
	}
	if maxLongLen > 0 {
		descStart += 4
	}
	descStart += 2 // padding before option

	var b bytes.Buffer
	b.WriteString("Usage:\n")
	b.WriteString(" ")
	fmt.Fprintf(&b, " %s %s", p.name, p.usage)
	b.WriteString("\n")
	if p.longDescription != "" {
		b.WriteString("\n")
		b.WriteString(wrapText(p.longDescription, cols, ""))
		b.WriteString("\n")
	}

	for gi, gname := range p.groups {
		first := true
		for _, o := range p.options {
			if o.group != gi {
				continue
			}
			if first {
				b.WriteString("\n")
				fmt.Fprintf(&b, "%s:\n", gname)
				first = false
			}
			line := "  "
			if o.short != 0 {
				line += "-" + string(o.short)
			} else if hasShort {
				line += "  "
			}
			if o.long != "" {
				if o.short != 0 {
					line += ", "
				} else if hasShort {
					line += "  "
				}
				line += "--" + o.long
			}
			if o.canArgument() {
				line += "="
			}
			b.WriteString(line)
			if o.description != "" {
				dw := descStart - len(line)
				if dw > 0 {
					b.WriteString(strings.Repeat(" ", dw))
				}
				desc := o.description
				if o.defValue != "" {
					desc = fmt.Sprintf("%s (default: %v)", o.description, o.defValue)
				}
				b.WriteString(wrapText(desc, cols-descStart, strings.Repeat(" ", descStart)))
			}
			b.WriteString("\n")
		}
	}
	return b.String()
}
EOF"}

