	b.WriteString("\n")
	if p.longDescription != "" {
		b.WriteString("\n")
		b.WriteString(wrapText(p.longDescription, cols, ""))
		b.WriteString("\n")
	}

	for gi, gname := range p.groups {
		first := true
		for _, o := range p.options {
			if o.group != gi {
				continue
			}
			if first {
				b.WriteString("\n")
				fmt.Fprintf(&b, "%s:\n", gname)
				first = false
			}
			line := "  "
			if o.short != 0 {
				line += "-" + string(o.short)
			} else if hasShort {
				line += "  "
			}
			if o.long != "" {
				if o.short != 0 {
					line += ", "
				} else if hasShort {
					line += "  "
				}
				line += "--" + o.long
			}
			if o.canArgument() {
				line += "="
			}
			b.WriteString(line)
