{"command":"cd /workspace; cat > pinger.go <<'EOF'
package main

import (
	"crypto/rand"
	"errors"
	"fmt"
	"log"
	"math"
	mrand "math/rand"
	"net"
	"os"
	"sync"
	"syscall"
	"time"
)

const (
	timeSliceLength = 8
	trackerLength   = 16
	protoICMP       = 1
	protoICMPv6     = 58
)

type tracker [16]byte

func newTracker() tracker {
	var t tracker
	if _, err := rand.Read(t[:]); err != nil {
		for i := range t {
			t[i] = byte(mrand.Intn(256))
		}
	}
	t[6] = (t[6] & 0x0f) | 0x40
	t[8] = (t[8] & 0x3f) | 0x80
	return t
}

// Packet describes a received echo reply.
type Packet struct {
	Rtt    time.Duration
	IPAddr *net.IPAddr
	Addr   string
	Nbytes int
	Seq    int
	TTL    int
	ID     int
}

// Statistics summarizes a ping session.
type Statistics struct {
	PacketsRecv           int
	PacketsSent           int
	PacketsRecvDuplicates int
	PacketLoss            float64
	IPAddr                *net.IPAddr
	Addr                  string
	MinRtt                time.Duration
	MaxRtt                time.Duration
	AvgRtt                time.Duration
	StdDevRtt             time.Duration
}

type Pinger struct {
	Interval time.Duration
	Timeout  time.Duration
	Count    int
	Size     int

	PacketsSent           int
	PacketsRecv           int
	PacketsRecvDuplicates int

	OnRecv   func(*Packet)
	OnFinish func(*Statistics)

	addr       string
	ipaddr     *net.IPAddr
	ipv4       bool
	privileged bool
	id         int
	sequence   int

	trackers []tracker
	awaiting map[tracker]map[int]struct{}

	done chan struct{}
	lock sync.Mutex

	statsMu   sync.RWMutex
	minRtt    time.Duration
	maxRtt    time.Duration
	avgRtt    time.Duration
	stdDevRtt time.Duration
	stddevm2  time.Duration

	logger *log.Logger
}

type rawPacket struct {
	bytes  []byte
	nbytes int
	ttl    int
}

func NewPinger(addr string) (*Pinger, error) {
	t := newTracker()
	p := &Pinger{
		Interval: time.Second,
		Timeout:  time.Duration(math.MaxInt64),
		Count:    -1,
		Size:     timeSliceLength + trackerLength,
		addr:     addr,
		id:       mrand.Intn(math.MaxUint16),
		trackers: []tracker{t},
		awaiting: map[tracker]map[int]struct{}{t: {}},
		done:     make(chan struct{}),
		logger:   log.New(os.Stderr, "", log.LstdFlags),
	}
	if err := p.Resolve(); err != nil {
		return nil, err
	}
	return p, nil
}

func (p *Pinger) Resolve() error {
	if len(p.addr) == 0 {
		return errors.New("addr cannot be empty")
	}
	ipaddr, err := net.ResolveIPAddr("ip", p.addr)
	if err != nil {
		return err
	}
	p.ipv4 = len(ipaddr.IP.To4()) == net.IPv4len
	p.ipaddr = ipaddr
	return nil
}

func (p *Pinger) Addr() string        { return p.addr }
func (p *Pinger) IPAddr() *net.IPAddr { return p.ipaddr }

func (p *Pinger) SetPrivileged(v bool) { p.privileged = v }

func (p *Pinger) Stop() {
	p.lock.Lock()
	defer p.lock.Unlock()
	select {
	case <-p.done:
	default:
		close(p.done)
	}
}

// ---------------------------------------------------------------------------
// connection handling

type icmpConn struct {
	udp  *net.UDPConn
	ip   *net.IPConn
	ipv4 bool
}

func (c *icmpConn) conn() interface {
	SetReadDeadline(time.Time) error
	Close() error
	SyscallConn() (syscall.RawConn, error)
} {
	if c.udp != nil {
		return c.udp
	}
	return c.ip
}

func (c *icmpConn) Close() error { return c.conn().Close() }

func (c *icmpConn) SetReadDeadline(t time.Time) error { return c.conn().SetReadDeadline(t) }

func (c *icmpConn) SetFlagTTL() error {
	rc, err := c.conn().SyscallConn()
	if err != nil {
		return err
	}
	var serr error
	err = rc.Control(func(fd uintptr) {
		if c.ipv4 {
			serr = syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IP, syscall.IP_RECVTTL, 1)
		} else {
			serr = syscall.SetsockoptInt(int(fd), syscall.IPPROTO_IPV6, syscall.IPV6_RECVHOPLIMIT, 1)
		}
	})
	if err != nil {
		return err
	}
	if serr != nil {
		return os.NewSyscallError("setsockopt", serr)
	}
	return nil
}

func (c *icmpConn) ReadFrom(b []byte) (int, int, error) {
	oob := make([]byte, 128)
	var n, oobn int
	var err error
	if c.udp != nil {
		n, oobn, _, _, err = c.udp.ReadMsgUDP(b, oob)
	} else {
		n, oobn, _, _, err = c.ip.ReadMsgIP(b, oob)
	}
	ttl := -1
	if err != nil {
		return n, ttl, err
	}
	if oobn > 0 {
		msgs, perr := syscall.ParseSocketControlMessage(oob[:oobn])
		if perr == nil {
			for _, m := range msgs {
				if len(m.Data) < 4 {
					continue
				}
				v := int(int32(nativeUint32(m.Data[:4])))
				if c.ipv4 && m.Header.Level == syscall.IPPROTO_IP && m.Header.Type == syscall.IP_TTL {
					ttl = v
				}
				if !c.ipv4 && m.Header.Level == syscall.IPPROTO_IPV6 && m.Header.Type == syscall.IPV6_HOPLIMIT {
					ttl = v
				}
			}
		}
	}
	return n, ttl, nil
}

func (c *icmpConn) WriteTo(b []byte, dst net.Addr) (int, error) {
	if c.udp != nil {
		return c.udp.WriteTo(b, dst)
	}
	return c.ip.WriteTo(b, dst)
}

func nativeUint32(b []byte) uint32 {
	// Linux on all supported architectures here is little endian for amd64/arm64.
	return uint32(b[0]) | uint32(b[1])<<8 | uint32(b[2])<<16 | uint32(b[3])<<24
}

func listenDatagramICMP(v4 bool) (*net.UDPConn, error) {
	family, proto := syscall.AF_INET, protoICMP
	if !v4 {
		family, proto = syscall.AF_INET6, protoICMPv6
	}
	s, err := syscall.Socket(family, syscall.SOCK_DGRAM, proto)
	if err != nil {
		return nil, os.NewSyscallError("socket", err)
	}
	var sa syscall.Sockaddr
	if v4 {
		sa = &syscall.SockaddrInet4{}
	} else {
		sa = &syscall.SockaddrInet6{}
	}
	if err := syscall.Bind(s, sa); err != nil {
		syscall.Close(s)
		return nil, os.NewSyscallError("bind", err)
	}
	f := os.NewFile(uintptr(s), "datagram-oriented icmp")
	c, err := net.FilePacketConn(f)
	f.Close()
	if err != nil {
		return nil, err
	}
	uc, ok := c.(*net.UDPConn)
	if !ok {
		c.Close()
		return nil, errors.New("unexpected connection type")
	}
	return uc, nil
}

func (p *Pinger) listen() (*icmpConn, error) {
	c := &icmpConn{ipv4: p.ipv4}
	var err error
	if p.privileged {
		network := "ip4:icmp"
		if !p.ipv4 {
			network = "ip6:ipv6-icmp"
		}
		var pc net.PacketConn
		pc, err = net.ListenPacket(network, "")
		if err == nil {
			c.ip = pc.(*net.IPConn)
		}
	} else {
		c.udp, err = listenDatagramICMP(p.ipv4)
	}
	if err != nil {
		p.Stop()
		return nil, err
	}
	return c, nil
}

// ---------------------------------------------------------------------------
// main loop

func (p *Pinger) Run() error {
	if p.ipaddr == nil {
		if err := p.Resolve(); err != nil {
			return err
		}
	}
	conn, err := p.listen()
	if err != nil {
		return err
	}
	defer conn.Close()
	return p.run(conn)
}

func (p *Pinger) run(conn *icmpConn) error {
	if err := conn.SetFlagTTL(); err != nil {
		return err
	}
	defer p.finish()

	recv := make(chan *rawPacket, 5)
	defer close(recv)

	var wg sync.WaitGroup
	var errOnce sync.Once
	var firstErr error
	setErr := func(err error) {
		if err != nil {
			errOnce.Do(func() { firstErr = err })
		}
	}

	wg.Add(2)
	go func() {
		defer wg.Done()
		defer p.Stop()
		setErr(p.recvICMP(conn, recv))
	}()
	go func() {
		defer wg.Done()
		defer p.Stop()
		setErr(p.runLoop(conn, recv))
	}()
	wg.Wait()
	return firstErr
}

type expBackoff struct {
	base   time.Duration
	maxExp int64
	c      int64
}

func (b *expBackoff) Get() time.Duration {
	if b.c < b.maxExp {
		b.c++
	}
