		r.nbytes = stripIPv4Header(r.nbytes, r.bytes)
	}
	b := r.bytes
	if len(b) < 4 {
		return fmt.Errorf("error parsing icmp message: message too short")
	}
	typ := b[0]
	if p.ipv4 && typ != 0 {
		return nil
	}
	if !p.ipv4 && typ != 129 {
		return nil
	}
	if len(b) < 8 {
		return fmt.Errorf("error parsing icmp message: message too short")
	}
	id := int(b[4])<<8 | int(b[5])
	seq := int(b[6])<<8 | int(b[7])
	data := b[8:]

	pkt := &Packet{
		Nbytes: r.nbytes,
		IPAddr: p.ipaddr,
		Addr:   p.addr,
		TTL:    r.ttl,
		ID:     p.id,
	}

	if !p.matchID(id) {
		return nil
	}
	if len(data) < timeSliceLength+trackerLength {
		return fmt.Errorf("insufficient data received; got: %d %v", len(data), data)
	}
	t, ok := p.findTracker(data)
	if !ok {
		return nil
	}
	ts := bytesToTime(data[:timeSliceLength])
	pkt.Rtt = receivedAt.Sub(ts)
	pkt.Seq = seq
	if _, inflight := p.awaiting[*t][seq]; !inflight {
		p.PacketsRecvDuplicates++
		return nil
	}
	delete(p.awaiting[*t], seq)
	p.updateStatistics(pkt)

	if p.OnRecv != nil {
		p.OnRecv(pkt)
	}
	return nil
}

func (p *Pinger) updateStatistics(pkt *Packet) {
	p.statsMu.Lock()
	defer p.statsMu.Unlock()

	p.PacketsRecv++
	if p.PacketsRecv == 1 || pkt.Rtt < p.minRtt {
		p.minRtt = pkt.Rtt
	}
	if pkt.Rtt > p.maxRtt {
		p.maxRtt = pkt.Rtt
	}
	n := time.Duration(p.PacketsRecv)
	delta := pkt.Rtt - p.avgRtt
	p.avgRtt += delta / n
	delta2 := pkt.Rtt - p.avgRtt
	p.stddevm2 += delta * delta2
	p.stdDevRtt = time.Duration(math.Sqrt(float64(p.stddevm2 / n)))
}

func (p *Pinger) Statistics() *Statistics {
	p.statsMu.RLock()
	defer p.statsMu.RUnlock()
	sent := p.PacketsSent
	loss := float64(sent-p.PacketsRecv) / float64(sent) * 100
	return &Statistics{
		PacketsSent:           sent,
		PacketsRecv:           p.PacketsRecv,
		PacketsRecvDuplicates: p.PacketsRecvDuplicates,
		PacketLoss:            loss,
		Addr:                  p.addr,
		IPAddr:                p.ipaddr,
		MaxRtt:                p.maxRtt,
		MinRtt:                p.minRtt,
		AvgRtt:                p.avgRtt,
		StdDevRtt:             p.stdDevRtt,
	}
}

func (p *Pinger) finish() {
	if p.OnFinish != nil {
		p.OnFinish(p.Statistics())
	}
}
EOF

