package main

import (
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

// Shell completion support, triggered through the GO_FLAGS_COMPLETION
// environment variable (compatible with go-flags style completion).

type completionItem struct {
	Item        string
	Description string
}

func argumentStartsOption(arg string) bool {
	return len(arg) > 0 && arg[0] == '-'
}

func (p *cliParser) completeOptionNames(prefix, match string, short bool) []completionItem {
	if short && len(match) != 0 {
		return []completionItem{{Item: prefix + match}}
	}
	var results []completionItem
	repeats := map[string]bool{}
	for _, o := range p.options {
		if strings.HasPrefix(o.long, match) {
			results = append(results, completionItem{Item: "--" + o.long, Description: o.description})
			if short {
				repeats[string(o.short)] = true
			}
		}
	}
	if short {
		for _, o := range p.options {
			name := string(o.short)
			if !repeats[name] && strings.HasPrefix(name, match) {
				results = append(results, completionItem{Item: "-" + name, Description: o.description})
			}
		}
	}
	return results
}

func (p *cliParser) complete(args []string) []completionItem {
	if len(args) == 0 {
		args = []string{""}
	}
	s := &parseState{args: append([]string(nil), args...)}
	var opt *optionDef

	for len(s.args) > 1 {
		arg := s.pop()
		if arg == "--" {
			opt = nil
			break
		}
		if argumentIsOption(arg) {
			_, optname, islong := stripOptionPrefix(arg)
			optname, argument := splitOption(optname, islong)
			if argument == nil {
				var o *optionDef
				canarg := true
				if islong {
					o = p.longNames[optname]
				} else {
					for i, r := range optname {
						sname := string(r)
						o = p.shortNames[sname]
						if o == nil {
							break
						}
						if i == 0 && o.canArgument() && len(optname) != len(sname) {
							canarg = false
							break
						}
					}
				}
				if o != nil && o.canArgument() && canarg {
					if len(s.args) > 1 {
						s.pop()
					} else {
						opt = o
					}
				}
			}
		} else {
			opt = nil
		}
	}

	lastarg := s.args[len(s.args)-1]
	var ret []completionItem

	if opt != nil {
		// Values of the available options have no completions.
		ret = nil
	} else if argumentStartsOption(lastarg) {
		_, optname, islong := stripOptionPrefix(lastarg)
		prefix := "-"
		if islong {
			prefix = "--"
		}
		optname, argument := splitOption(optname, islong)
		if argument == nil && !islong {
			rname, _ := utf8.DecodeRuneInString(optname)
			sname := string(rname)
			if o := p.shortNames[sname]; o != nil && o.canArgument() {
				ret = nil
			} else {
				ret = p.completeOptionNames(prefix, optname, true)
			}
		} else if argument != nil {
			ret = nil
		} else if islong {
			ret = p.completeOptionNames(prefix, optname, false)
		} else {
			ret = p.completeOptionNames(prefix, optname, true)
		}
	}

	sort.SliceStable(ret, func(i, j int) bool { return ret[i].Item < ret[j].Item })
	return ret
}

func printCompletions(items []completionItem, showDescriptions bool) {
	if showDescriptions && len(items) > 1 {
		maxl := 0
		for _, v := range items {
			if len(v.Item) > maxl {
				maxl = len(v.Item)
			}
		}
		for _, v := range items {
			fmt.Printf("%s", v.Item)
			if len(v.Description) > 0 {
				fmt.Printf("%s  # %s", strings.Repeat(" ", maxl-len(v.Item)), v.Description)
			}
			fmt.Printf("\n")
		}
	} else {
		for _, v := range items {
			fmt.Println(v.Item)
		}
	}
}
EOF
